import{_ as l,o as i,c as e,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"帳單報銷說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/11-bill-reimbursement-guide.md","filePath":"v1/zh-HK/guide/11-bill-reimbursement-guide.md"}'),t={name:"v1/zh-HK/guide/11-bill-reimbursement-guide.md"};function o(h,a,n,d,u,s){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="帳單報銷說明" tabindex="-1">帳單報銷說明 <a class="header-anchor" href="#帳單報銷說明" aria-label="Permalink to &quot;帳單報銷說明&quot;">​</a></h1><h2 id="_1-這是什麼功能" tabindex="-1">1. 這是什麼功能 <a class="header-anchor" href="#_1-這是什麼功能" aria-label="Permalink to &quot;1. 這是什麼功能&quot;">​</a></h2><p>「報銷」用來記錄一筆支出後，後續由他人/公司把錢補回來的情況（例如差旅、辦公用品、代墊費用等）。</p><p>在考拉記帳中，報銷的核心邏輯是：</p><ul><li>你先記一筆「支出」，並標記為「可報銷」</li><li>當這筆支出完成報銷時，系統會自動新增一筆「報銷入帳」的收入帳單，並把金額加回到你指定的帳戶</li></ul><p>這樣做的好處是：</p><ul><li>原支出仍然保留（方便追溯用途）</li><li>報銷回款也有記錄（方便核對入帳帳戶與時間）</li><li>統計口徑清晰：支出與報銷入帳分開記錄</li></ul><h2 id="_2-適用場景" tabindex="-1">2. 適用場景 <a class="header-anchor" href="#_2-適用場景" aria-label="Permalink to &quot;2. 適用場景&quot;">​</a></h2><ul><li>公司報銷（交通、住宿、餐飲、辦公用品等）</li><li>朋友/家人代付後再轉帳給你（也可用報銷方式記錄）</li><li>代墊款項需要後續收回</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><h3 id="_3-1-建立「可報銷」的支出" tabindex="-1">3.1 建立「可報銷」的支出 <a class="header-anchor" href="#_3-1-建立「可報銷」的支出" aria-label="Permalink to &quot;3.1 建立「可報銷」的支出&quot;">​</a></h3><ol><li>新增一筆支出帳單</li><li>在建立/編輯頁面勾選「報銷」（或類似的「可報銷/待報銷」選項）</li><li>儲存後，該帳單在列表中會顯示「待報銷/已報銷」等狀態提示</li></ol><h3 id="_3-2-對支出執行「報銷」" tabindex="-1">3.2 對支出執行「報銷」 <a class="header-anchor" href="#_3-2-對支出執行「報銷」" aria-label="Permalink to &quot;3.2 對支出執行「報銷」&quot;">​</a></h3><ol><li>在帳單列表找到「待報銷」的支出</li><li>對該帳單左滑，選擇「報銷」</li><li>在報銷頁面中設定： <ul><li>金額：預設等於原支出金額，可改為實際報銷金額</li><li>時間：預設今天，可改為實際入帳日期</li><li>入帳帳戶：選擇報銷款實際打入的帳戶</li><li>備註：可選</li></ul></li><li>點選「完成/儲存」</li></ol><p>儲存後，會新增一筆「報銷入帳」的收入帳單，用來記錄回款。</p><h2 id="_4-使用規則與注意事項" tabindex="-1">4. 使用規則與注意事項 <a class="header-anchor" href="#_4-使用規則與注意事項" aria-label="Permalink to &quot;4. 使用規則與注意事項&quot;">​</a></h2><ul><li>只有「支出」且已標記為「可報銷」的帳單才能進行報銷。</li><li>拆分與報銷互斥：已拆分的帳單（包含拆分後的子帳單/拆分容器）無法開啟報銷流程；已標記為可報銷的支出也無法再進行拆分。建議先確認是否需要報銷；如有需要，可先把費用拆分清楚，再將需要報銷的部分另外記為可報銷支出。</li><li>已經生成過「報銷入帳」的支出，預設不支援重複報銷（避免重複入帳）。</li><li>若你刪除了「報銷入帳」那筆收入記錄，原支出會回到「待報銷」狀態（可再次執行報銷）。</li><li>報銷入帳會計入收入統計；原支出仍會計入支出統計，這是為了讓收支流向更清晰。</li></ul><h2 id="_5-常見問題" tabindex="-1">5. 常見問題 <a class="header-anchor" href="#_5-常見問題" aria-label="Permalink to &quot;5. 常見問題&quot;">​</a></h2><h3 id="q1-報銷和退款有什麼不同" tabindex="-1">Q1：報銷和退款有什麼不同？ <a class="header-anchor" href="#q1-報銷和退款有什麼不同" aria-label="Permalink to &quot;Q1：報銷和退款有什麼不同？&quot;">​</a></h3><ul><li>退款：針對一筆帳單發生退回，通常用來抵銷原帳單影響（新增一筆負數記錄）</li><li>報銷：針對一筆「可報銷的支出」，後續收到補回款（新增一筆報銷入帳的收入記錄）</li></ul><h3 id="q2-報銷款打到別的帳戶怎麼辦" tabindex="-1">Q2：報銷款打到別的帳戶怎麼辦？ <a class="header-anchor" href="#q2-報銷款打到別的帳戶怎麼辦" aria-label="Permalink to &quot;Q2：報銷款打到別的帳戶怎麼辦？&quot;">​</a></h3><p>在報銷頁面把「入帳帳戶」改為實際入帳帳戶即可。</p><h3 id="q3-只報銷了部分金額要怎麼記" tabindex="-1">Q3：只報銷了部分金額要怎麼記？ <a class="header-anchor" href="#q3-只報銷了部分金額要怎麼記" aria-label="Permalink to &quot;Q3：只報銷了部分金額要怎麼記？&quot;">​</a></h3><p>把報銷金額改為實際報銷金額即可。未報銷的差額仍會保留在原支出上，方便你後續核對。</p>',24)])])}const b=l(t,[["render",o]]);export{c as __pageData,b as default};
